package local.phonecommander.observer;
import java.net.*;import java.io.*;import java.security.*;import java.util.*;import org.json.*;
final class Hub {
 static volatile String token="";static volatile long expires;static volatile byte[] frame;static volatile long frameAt;static volatile int sourceWidth,sourceHeight;static volatile long sequence;static final ArrayDeque<JSONObject> events=new ArrayDeque<>();static ServerSocket server;static final java.util.concurrent.Semaphore clients=new java.util.concurrent.Semaphore(4);
 static synchronized void start(){stop();byte[] key=new byte[32];new SecureRandom().nextBytes(key);StringBuilder b=new StringBuilder();for(byte x:key)b.append(String.format("%02x",x&255));token=b.toString();expires=System.currentTimeMillis()+600000;
  final String generation=token;new Thread(()->{try{ServerSocket socket=new ServerSocket(38947,4,InetAddress.getByName("127.0.0.1"));synchronized(Hub.class){if(!generation.equals(token)){socket.close();return;}server=socket;}while(!socket.isClosed()){Socket client=socket.accept();if(!clients.tryAcquire()){client.close();continue;}new Thread(()->{try{serve(client);}finally{clients.release();}},"observer-client").start();}}catch(IOException ignored){synchronized(Hub.class){if(generation.equals(token))stop();}}},"observer-listener").start();
 }
 static synchronized void stop(){token="";expires=0;frame=null;events.clear();if(server!=null)try{server.close();}catch(IOException ignored){}server=null;}
 static boolean active(){return !token.isEmpty()&&System.currentTimeMillis()<expires;}
 static synchronized void event(JSONObject event){if(!active())return;try{event.put("sequence",++sequence);events.addLast(event);while(events.size()>128)events.removeFirst();}catch(JSONException ignored){}}
 static void serve(Socket socket){try(Socket c=socket){c.setSoTimeout(5000);BufferedReader reader=new BufferedReader(new InputStreamReader(c.getInputStream(),"US-ASCII"));String first=reader.readLine();if(first==null||first.length()>512)return;String auth="";int total=first.length();for(String line;(line=reader.readLine())!=null&&!line.isEmpty();){total+=line.length();if(total>4096)return;if(line.startsWith("Authorization: Bearer "))auth=line.substring(22);}
  OutputStream out=c.getOutputStream();if(!active()||!MessageDigest.isEqual(auth.getBytes("US-ASCII"),token.getBytes("US-ASCII"))){out.write("HTTP/1.1 403 Forbidden\r\nContent-Length: 0\r\nConnection: close\r\n\r\n".getBytes("US-ASCII"));return;}
  if(first.equals("GET /frames HTTP/1.1")){out.write("HTTP/1.1 200 OK\r\nContent-Type: multipart/x-mixed-replace; boundary=frame\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n".getBytes("US-ASCII"));long previous=0;while(active()&&auth.equals(token)){byte[] bytes=frame;long at=frameAt;if(bytes!=null&&at!=previous){out.write(("--frame\r\nContent-Type: image/jpeg\r\nContent-Length: "+bytes.length+"\r\nX-Captured-At: "+at+"\r\nX-Source-Width: "+sourceWidth+"\r\nX-Source-Height: "+sourceHeight+"\r\n\r\n").getBytes("US-ASCII"));out.write(bytes);out.write("\r\n".getBytes("US-ASCII"));out.flush();previous=at;}Thread.sleep(15);}}
  else if(first.equals("GET /events HTTP/1.1")){JSONArray result=new JSONArray();synchronized(Hub.class){for(JSONObject event:events)result.put(event);}byte[] bytes=result.toString().getBytes("UTF-8");out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nCache-Control: no-store\r\nContent-Length: "+bytes.length+"\r\nConnection: close\r\n\r\n").getBytes("US-ASCII"));out.write(bytes);}
 }catch(Exception ignored){}}
}